-- Catalog disciplines get a one-sentence description (#14). Copies whose
-- description is still the catalog's former long text get the new one;
-- descriptions the handler edited stay as they are.
UPDATE "discipline" d
SET "description" = texts.short
FROM (VALUES
    ('agility', 'Pes probíhá parkur ze skoků, tunelů, slalomu a zónových překážek a psovod ho vede tělem a povely. Začít se dá už se štěnětem: start z odložení, práce na obou stranách, sebeovládání a nízké překážky. Dokud nemá pes uzavřené růstové chrupavky (obvykle 12–18 měsíců podle velikosti), vynechte plné výšky skoků, plné zóny i zavřený slalom. Před začátkem nechte psa prohlédnout veterinářem. Na závody FCI může pes nejdřív v 18 měsících.', 'Pes probíhá parkur ze skoků, tunelů a slalomu a psovod ho vede tělem a povely.'),
    ('agility', 'The dog runs a course of jumps, tunnels, weave poles and contact obstacles while you handle them with your body and cues. Puppies can start foundations: start-line stay, working on both sides, self-control and low equipment. Until the growth plates close (usually 12–18 months, depending on size), skip full-height jumps, full contacts and closed weaves. Get a vet check before you start. FCI trials accept dogs from 18 months.', 'The dog runs a course of jumps, tunnels and weaves, guided by your body and cues.'),
    ('hoopers', 'Pes probíhá trať z obručí, barelů, branek a tunelů a psovod ho vede z prostoru psovoda (2 × 2 m) jen hlasem a tělem. Neskáče se a nejsou tu zóny, proto je hoopers šetrný ke kloubům a hodí se pro mladé, starší i těžší psy. Hodnotí se čistý a plynulý běh, ne čas. Na závodech FCI se pes měří nejdřív v 15 měsících. U psa s kloubními potížemi se nejdřív poraďte s veterinářem.', 'Pes probíhá trať z obručí, barelů a tunelů a psovod ho vede z jednoho místa hlasem a tělem.'),
    ('hoopers', 'The dog runs a course of hoops, barrels, gates and tunnels while you handle them from a 2 × 2 m handling area, using only voice and body. There are no jumps or contacts, so hoopers is easy on the joints and suits young, senior and heavier dogs. A clear, flowing run counts for more than speed. In FCI competition, dogs are measured from 15 months. If your dog has joint problems, check with your vet first.', 'The dog runs hoops, barrels and tunnels while you guide them from one spot by voice and body.'),
    ('disc-dog', 'Psovod hází disk, pes ho chytá a přináší zpět. Začíná se hrou, kutálením disku po zemi a krátkými nízkými hody, později přibývají delší hody (toss and fetch). Používejte měkké disky určené pro psy. Do roka (u velkých plemen déle) neházejte vysoko, aby pes nemusel skákat. Odrazy od psovoda (vaulty) do začátků nepatří; pokud vůbec, tak až po 18 měsících, po prohlídce u veterináře a pod vedením zkušeného trenéra. Trénujte na trávě a ne v horku.', 'Psovod hází disk, pes ho chytá a přináší zpět.'),
    ('disc-dog', 'The handler throws the disc, the dog catches it and brings it back. Start with play, rolled discs and short low throws, then build up to longer throws (toss and fetch). Use soft discs made for dogs. Until about a year old (longer for large breeds), don''t throw high, so the dog doesn''t need to leap. Vaults off the handler are not for beginners: if at all, only after 18 months, a vet check and hands-on coaching. Train on grass and avoid the heat.', 'You throw a disc, and your dog catches it and brings it back.'),
    ('obedience', 'Základní slušné chování na vodítku i mezi lidmi podle testu AKC Canine Good Citizen, s povely, jaké znáte z cvičiště (k noze, sedni, lehni, zůstaň). Hodí se pro každého psa zhruba od 5 měsíců i pro dospělé psy bez výcviku. Pracujte jen s odměnou, na plochém obojku nebo dobře padnoucím postroji, bez stahovacích, ostnatých a elektrických obojků.', 'Slušné chování na vodítku i mezi lidmi a základní povely sedni, lehni a zůstaň.'),
    ('obedience', 'Everyday manners on lead and around people, based on the AKC Canine Good Citizen test. Suits any dog from about 5 months, as well as untrained adults. Train with rewards only, on a flat collar or a well-fitted harness; no choke, prong or electronic collars.', 'Good manners on lead and around people, plus sit, down and stay.'),
    ('recall', 'Přivolání, na které se dá spolehnout na procházce, v parku i u jiných psů: od her doma přes dlouhé vodítko až po přivolání od rozptýlení. Hodí se pro štěňata i dospělé psy. Volejte jednou, každý příchod odměňte a nikdy nevolejte psa kvůli něčemu nepříjemnému. Na volno pouštějte jen tam, kde je to dovolené a bezpečné; do té doby používejte dlouhé vodítko připnuté k postroji.', 'Přivolání, na které se dá spolehnout na procházce i u jiných psů.'),
    ('recall', 'A recall you can trust on walks, in the park and around other dogs, from games at home through a long line to recalls away from distractions. Suits puppies and adults. Call once, reward every recall and never call your dog for something unpleasant. Only let them off lead where it is allowed and safe; until then use a long line clipped to a harness.', 'A recall you can rely on, on walks and around other dogs.'),
    ('puppy', 'Bezpečné seznamování štěněte se světem a první domácí návyky. Nejdůležitější období socializace jsou první tři měsíce života, proto začněte hned po příchodu domů (zhruba od 8 týdnů). Do štěněcí školky může štěně zhruba týden po první vakcinaci a odčervení; o místech, kde chodí cizí psi, se poraďte s veterinářem. Každý zážitek má být příjemný: postupujte pomalu a při známkách strachu přidejte odstup.', 'Bezpečné seznamování štěněte se světem a první domácí návyky.'),
    ('puppy', 'Safely introducing a puppy to the world, plus first house manners. The first three months of life are the key socialisation window, so start as soon as the puppy comes home (around 8 weeks). Puppy classes are fine from about a week after the first vaccination and deworming; ask your vet about places used by unknown dogs. Every experience should be pleasant: go slowly and add distance at any sign of fear.', 'Safely introducing a puppy to the world, plus first house manners.'),
    ('calm', 'Pes, který umí doma odpočívat, zvládne chvíle bez vás a nedělá drama z odchodů. Hodí se pro štěňata i dospělé psy, zvlášť po adopci. Tempo určují reakce psa; nikdy ho nenechte „vyplakat se“. Dospělého psa nenechávejte samotného déle než asi 4 hodiny. Pokud pes v samotě vyje, ničí, čůrá nebo se zraňuje, může jít o separační úzkost: poraďte se s veterinářem a veterinárním etologem.', 'Pes, který umí doma odpočívat a zvládne chvíle bez vás.'),
    ('calm', 'A dog who can rest at home, cope with time on their own and take your departures in their stride. Suits puppies and adults, especially newly adopted dogs. Let the dog''s reactions set the pace and never let them “cry it out”. Don''t leave an adult dog alone for more than about 4 hours. If your dog howls, destroys things, soils or hurts themselves when alone, it may be separation anxiety: talk to your vet and a qualified behaviourist.', 'A dog who can settle at home and cope with time on their own.'),
    ('tricks', 'Triky pro radost, procvičení hlavy a lepší spolupráci. Postup se volně drží úrovní AKC Trick Dog: začátečnické triky s návnadou, pak triky bez pamlsku v ruce a nakonec krátká sestava. Hodí se pro psy každého věku. Dokud štěně neukončí růst (zhruba 12–18 měsíců podle velikosti plemene), vynechte skoky a triky na zadních nohách a cvičte na protiskluzovém povrchu.', 'Triky pro radost, procvičení hlavy a lepší spolupráci.'),
    ('tricks', 'Tricks for fun, mental exercise and better teamwork, loosely following the AKC Trick Dog levels: novice tricks with a lure, then tricks with no food in your hand, and finally a short routine. Suits dogs of any age. Until a puppy has finished growing (roughly 12–18 months depending on size), skip jumps and tricks on the hind legs, and train on a non-slip surface.', 'Tricks for fun, mental exercise and better teamwork.'),
    ('canicross', 'Běh se psem, který v tažném postroji táhne psovoda; je k jeho bedernímu pásu připnutý šňůrou s amortizérem. Hodí se pro zdravé a aktivní psy i psovody, kteří rádi běhají v terénu. Začněte po prohlídce u veterináře, nejdřív ve 12 měsících (velká plemena v 15–18 měsících). Běhejte na měkkém povrchu, při teplotě pod 15–20 °C, kontrolujte tlapky a jako začátečníci nejvýš 3× týdně.', 'Běh se psem, který vás v tažném postroji táhne na šňůře s amortizérem.'),
    ('canicross', 'Running with your dog pulling you in a harness, clipped to your waist belt with a bungee line. Suits healthy, active dogs and handlers who enjoy trail running. Start after a vet check and not before 12 months (large breeds 15–18 months). Run on soft ground below 15–20 °C, check the paws, and as a beginner keep to at most 3 runs a week.', 'Running with your dog pulling you in a harness on a bungee line.'),
    ('bikejoring', 'Pes v tažném postroji běží před horským kolem, ke kterému je připnutý šňůrou s amortizérem přes rameno (anténu). Hodí se pro psy, kteří už zvládají povely z canicrossu. Pes musí být plně dospělý (12–18 měsíců) a mít za sebou prohlídku u veterináře. Přilba a rukavice jsou povinné. Jezděte po měkkých a rovných cestách při teplotě pod 15 °C, kratší úseky než při canicrossu a zpočátku 1–2× týdně.', 'Pes v tažném postroji běží před horským kolem.'),
    ('bikejoring', 'The dog runs in a pulling harness in front of a mountain bike, on a bungee line attached via a bike antenna. Suits dogs that already know their canicross cues. The dog must be fully grown (12–18 months) and vet-checked. A helmet and gloves are a must. Ride flat, soft trails below 15 °C, keep runs shorter than in canicross, and start with 1–2 sessions a week.', 'Your dog runs in a pulling harness in front of a mountain bike.'),
    ('dogtrekking', 'Dálkový pochod se psem v postroji připnutým k bedernímu pásu nebo na vodítku. Trasu hledáte podle mapy a procházíte kontroly. Akce mají od zhruba 30 km (midy) po 80–100 km i víc, s povinnou výbavou: mapa, čelovka, miska, voda, lékárnička a dvě botičky na psa. Pes musí mít alespoň 12 měsíců a být zdravý; krátkonosým plemenům se nehodí. Kondici i tlapky budujte postupně a v teple dbejte na stín a dostatek vody.', 'Dálkový pochod se psem podle mapy přes kontroly.'),
    ('dogtrekking', 'Long-distance hiking with your dog in a harness clipped to your waist belt or on a lead, finding your way by map between checkpoints. Events range from about 30 km (mid) to 80–100 km and more, with mandatory gear: map, headlamp, bowl, water, first-aid kit and two booties per dog. The dog must be at least 12 months old and healthy; it is not suitable for flat-faced breeds. Build fitness and paw pads gradually, and plan for shade and plenty of water in warm weather.', 'Long-distance hiking with your dog, navigating by map between checkpoints.'),
    ('competitive-obedience', 'Sportovní poslušnost podle třídy OB-Z: odložení ve skupině, chůze u nohy, odložení za chůze, přivolání, vyslání do čtverce, držení činky, ovladatelnost na dálku a skok. Hodí se pro psy, kteří už znají sedni, lehni a přivolání. Na zkoušku musí mít pes aspoň 10 měsíců. Skok trénujte nízko (v OB-Z nejvýš 50 cm) a u mladého psa ho zvyšujte až po ukončení růstu a prohlídce u veterináře.', 'Sportovní poslušnost pro začátečnickou třídu: chůze u nohy, odložení, přivolání a další cviky.'),
    ('competitive-obedience', 'Competitive obedience based on the Czech beginner class (OB-Z): group stay, heelwork, positions on the move, recall, send-away to a square, dumbbell hold, distance control and a jump. Suits dogs that already know sit, down and recall. Dogs must be at least 10 months old to enter. Keep the jump low (50 cm max in this class) and raise it for a young dog only once they have finished growing and a vet has checked them.', 'Competitive obedience for the beginner class: heelwork, stays, recall and more.'),
    ('rally-obedience', 'Tým prochází parkur s kartami (u začátečníků 15–18 karet) a na každé provede předepsaný cvik: zastavení, polohy, obraty, změny tempa, předsednutí, slalom či spirálu. Pochvala a mluvení na psa jsou vítané a v začátečnické třídě může pes jít na volném vodítku. Hodí se pro každého psa od 10 měsíců, i pro starší a méně sportovní psy.', 'Tým prochází parkur s kartami a na každé provede předepsaný cvik.'),
    ('rally-obedience', 'The team works through a course of signs (15–18 at beginner level) and performs the exercise shown on each: halts, positions, turns, pace changes, fronts, slalom or spiral. Praise and talking to the dog are encouraged, and in the beginner class the dog may work on a loose lead. Suits any dog from 10 months, including older and less athletic dogs.', 'You and your dog work through a course of signs, performing the exercise on each.'),
    ('dogdancing', 'Sestava na hudbu, ve které pes s psovodem předvádějí prvky v pozicích u nohy (heelwork to music) a volné triky (freestyle). Cviky vycházejí z postupových zkoušek 1. stupně, na které může pes od 10 měsíců. Hodí se pro psy všech velikostí. Psa rozcvičujte, trénujte na neklouzavém povrchu a u mladých psů vynechte skoky, panáčkování a dlouhé couvání.', 'Sestava na hudbu z prvků u nohy a volných triků.'),
    ('dogdancing', 'A routine to music in which dog and handler perform moves in heel positions (heelwork to music) and free tricks (freestyle). The exercises follow the Czech level 1 dog dancing tests, open to dogs from 10 months. Suits dogs of any size. Warm the dog up, train on a non-slip surface, and leave out jumps, sitting up on the hind legs and long back-ups for young dogs.', 'A routine to music made of heelwork moves and free tricks.'),
    ('nosework', 'Pes hledá ukrytý pachový vzorek (skořici nebo pomerančovou kůru, jak je používá Nosework CZ) v krabicích, v místnosti i venku a psovod ohlásí nález. Hodí se pro každého psa bez ohledu na věk a plemeno, i pro psy plaché nebo po zranění. Se štěnětem můžete hrát krabicovou hru hned, na zkoušku základního stupně musí mít pes 10 měsíců. Pracuje se na volno nebo na volném vodítku, jen v obojku či postroji, který psa netlačí.', 'Pes hledá ukrytý pachový vzorek v krabicích, v místnosti i venku.'),
    ('nosework', 'The dog searches for a hidden odour (cinnamon or orange peel, as used by Nosework CZ) in boxes, rooms and outdoors, and the handler calls the find. It suits any dog of any age or breed, including shy dogs and dogs recovering from injury. Puppies can play the box game straight away; the Czech basic-level trial requires a dog of at least 10 months. Dogs work off lead or on a slack lead, only in a collar or harness that doesn''t pinch.', 'Your dog searches for a hidden scent in boxes, rooms and outdoors.'),
    ('tracking', 'Pes jde s nízkým nosem krok po kroku po stopě člověka přes trávu nebo pole a zalehnutím označuje předměty, které na ní kladeč nechal. Stopa je součástí zkoušek podle NZŘ (ZM, ZVV) i FCI IGP. Začít se dá už se štěnětem na krátkých stopách s pamlsky, na zkoušku ZM musí mít pes 12 měsíců. Pracuje se v postroji na 10m stopovací šňůře. Netrénujte v poledním horku a po tréninku psa prohlédněte kvůli klíšťatům a poraněným tlapkám.', 'Pes jde s nízkým nosem po stopě člověka a označuje předměty na ní.'),
    ('tracking', 'The dog follows a person''s footstep track over grass or fields with their nose down, step by step, and indicates the articles the tracklayer dropped by lying down. Tracking is part of Czech NZŘ trials (ZM, ZVV) and FCI IGP. Puppies can start on short food tracks; the ZM trial requires a dog of at least 12 months. The dog works in a harness on a 10 m tracking line. Avoid midday heat and check the dog for ticks and sore paws after each session.', 'Your dog follows a person''s track nose down and indicates the articles on it.'),
    ('mantrailing', 'Pes v postroji na dlouhém vodítku (5–10 m) hledá v přírodě i ve městě konkrétního člověka podle pachu, který si načichne z pachového předmětu. Protože pes nikdy nejde na volno, hodí se i pro psy bez spolehlivého přivolání nebo pro psy reaktivní. Štěně si může hrát na krátká hledání, systematický trénink se obvykle začíná kolem 6 měsíců. Stopy bývají dlouhé, proto psa s ortopedickými potížemi nechte nejdřív prohlédnout veterinářem a v teple noste vodu.', 'Pes na dlouhém vodítku hledá konkrétního člověka podle jeho pachu.'),
    ('mantrailing', 'The dog, in a harness on a long line (5–10 m), finds one particular person, in the countryside or in town, by the scent they take from a scent article. Because the dog never works off lead, it suits dogs without a reliable recall and reactive dogs. Puppies can play short searches; systematic training usually starts around 6 months. Trails can be long, so have a dog with orthopaedic issues checked by a vet first and carry water in warm weather.', 'On a long line, your dog finds one particular person by their scent.')
) AS texts(key, long, short)
WHERE d."catalogKey" = texts.key AND d."description" = texts.long;
